-- Every slot of the grid from the live records.
VRFW.battle_bay_pages.ICON_REQ = 3190452549
VRFW.battle_bay_pages.ICON_LOADING = 1277042906
VRFW.battle_bay_pages.TEAM_INFO = 2151743654
VRFW.battle_bay_pages.PRE_KEY = 1215818925
VRFW.battle_bay_pages.CLOCK = 3103285012
VRFW.battle_bay_pages.PRELOAD_MS = 1200
VRFW.battle_bay_pages.REVEAL_MS = 600
VRFW.battle_bay_pages.LATE_MS = 5000
VRFW.battle_bay_pages.PRELOAD_STEPS = 400
VRFW.battle_bay_pages.REVEAL_STEPS = 200
VRFW.battle_bay_pages.LATE_STEPS = 1600
VRFW.battle_bay_pages.SETTLE = 2
VRFW.battle_bay_pages.LOG_FRAMES = 6
VRFW.battle_bay_pages.hidden_slots = {}
VRFW.battle_bay_pages.drawn = {}
VRFW.battle_bay_pages.spares = {}
VRFW.battle_bay_pages.pend = nil

function VRFW.battle_bay_pages.grid_slot_count()
  return funcLuaMenuCommand(1175615627, VRFW.battle_bay_pages.GRID) or 0
end

-- milliseconds of the framework's monotonic clock, nil without it
function VRFW.battle_bay_pages.now()
  local t = VRFW.host.command(VRFW.battle_bay_pages.CLOCK)
  if type(t) == "number" then
    return t
  end
  return nil
end

-- the per-cell state string, whether any cell is loading, and the loading cells (slot -> true)
function VRFW.battle_bay_pages.load_state()
  local B = VRFW.battle_bay_pages
  local teams = B.pend ~= nil and B.pend.teams or {}
  local t, busy, loading = {}, false, {}
  for i = 0, VRFW.battle_bay_pages.grid_slot_count() - 1 do
    if teams[i] == nil and B.hidden_slots[i] == true then
      t[#t + 1] = "-"
    elseif funcLuaMenuCommand(B.ICON_LOADING, B.GRID, i) == true then
      t[#t + 1] = "1"
      busy = true
      loading[i] = true
    else
      t[#t + 1] = "0"
    end
  end
  return table.concat(t), busy, loading
end

function VRFW.battle_bay_pages.release_spares()
  local B = VRFW.battle_bay_pages
  for i in pairs(B.spares) do
    VRFW.host.menu_command(4176779611 --[[reset icon]], B.GRID, i, B.PRE_KEY)
  end
  B.spares = {}
end

-- Showing _pos_enjoy_list01 turns its WHOLE subtree on, the 1P / 2P mark plates included
VRFW.battle_bay_pages.marks = {}
VRFW.battle_bay_pages.after_restore_marks = VRFW.battle_bay_pages.after_restore_marks or {}

local function restore_marks(i)
  local B = VRFW.battle_bay_pages
  local a = B.marks[i]
  if a ~= nil and UpdateEmblemIconMesh ~= nil then
    local ok = pcall(UpdateEmblemIconMesh, table.unpack(a, 1, a.n))
    if ok then
      return (a[3] == true or a[4] == true) and "P" or "c"
    end
  end
  funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, 3808539401 --[[_pos_enjoy_list01_p1]], false, i)
  funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, 2047402675 --[[_pos_enjoy_list01_p2]], false, i)
  funcLuaMenuCommand(3405944500, B.GRID, 2291119251 --[[_enjoy_list_p2_base02]], false, i)
  funcLuaMenuCommand(3405944500, B.GRID, 100709232 --[[_enjoy_list_p1_base02]], false, i)
  funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, 1061671357, false, i)
  funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, 2790162439, false, i)
  return "f"
end

function VRFW.battle_bay_pages.restore_marks(i)
  local r = restore_marks(i)
  for _, f in ipairs(VRFW.battle_bay_pages.after_restore_marks) do
    pcall(f, i)
  end
  return r
end

function VRFW.battle_bay_pages.show_nodes(only)
  local B = VRFW.battle_bay_pages
  local t = {}
  for i = 0, VRFW.battle_bay_pages.grid_slot_count() - 1 do
    if only ~= nil and not only[i] then
      t[#t + 1] = "="
    elseif B.hidden_slots[i] ~= true then
      funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, B.EMBLEM_NODE, true, i)
      t[#t + 1] = VRFW.battle_bay_pages.restore_marks(i)
    else
      t[#t + 1] = "-"
    end
  end
  return table.concat(t)
end

function VRFW.battle_bay_pages.cancel(why)
  local B = VRFW.battle_bay_pages
  local p = B.pend
  B.pend = nil
  if p ~= nil then
    VRFW.battle_bay_pages.log("turn cancelled", why, "phase", p.phase)
    if p.phase ~= "preload" then
      VRFW.battle_bay_pages.show_nodes(p.changed)
    end
  end
  VRFW.battle_bay_pages.release_spares()
end

-- has the current phase of turn p lasted ms (wall time) / steps (without the clock)?
function VRFW.battle_bay_pages.over(p, ms, steps)
  if p.t_phase ~= nil then
    local now = VRFW.battle_bay_pages.now()
    if now ~= nil then
      return now - p.t_phase >= ms
    end
  end
  return p.frames >= steps
end

function VRFW.battle_bay_pages.ms(from)
  local now = VRFW.battle_bay_pages.now()
  if now == nil or from == nil then
    return -1
  end
  return now - from
end

function VRFW.battle_bay_pages.slots(set)
  local t = {}
  for i in pairs(set) do
    t[#t + 1] = i
  end
  table.sort(t)
  return table.concat(t, " ")
end

function VRFW.battle_bay_pages.preload(what)
  local B = VRFW.battle_bay_pages
  -- A turn during the previous turn's reveal.
  local carry = {}
  local old = B.pend
  if old ~= nil and old.phase ~= "preload" and old.changed ~= nil then
    for i in pairs(old.changed) do
      carry[i] = true
    end
  elseif old ~= nil and old.carry ~= nil then
    carry = old.carry
  end
  VRFW.battle_bay_pages.release_spares()
  local teams, asked = {}, 0
  for i = 0, VRFW.battle_bay_pages.grid_slot_count() - 1 do
    local team = funcLuaCommand(B.SLOT, i)
    if type(team) == "number" and team ~= 0 then
      teams[i] = team
      if B.drawn[i] ~= team or B.hidden_slots[i] == true then
        local ok, emblem = funcLuaCommand(B.TEAM_INFO, team, 6, 0)
        if ok then
          funcLuaMenuCommand(B.ICON_REQ, B.GRID, i, B.PRE_KEY, B.PRE_KEY, emblem, false, false)
          B.spares[i] = true
          asked = asked + 1
        end
      end
    end
  end
  local now = VRFW.battle_bay_pages.now()
  B.pend = {phase = "preload", frames = 0, teams = teams, page = what, carry = carry, t0 = now, t_phase = now,
            preload_ms = -1, reveal_ms = -1}
  VRFW.battle_bay_pages.log("preload", what, "crests", asked)
  if asked == 0 then
    VRFW.battle_bay_pages.swap()
  end
end

function VRFW.battle_bay_pages.swap()
  local B = VRFW.battle_bay_pages
  local p = B.pend or {frames = 0, teams = {}}
  local changed = VRFW.battle_bay_pages.redraw(true)
  for i in pairs(p.carry or {}) do
    if B.hidden_slots[i] ~= true then
      changed[i] = true
    end
  end
  local now = VRFW.battle_bay_pages.now()
  B.pend = {phase = "reveal", frames = 0, teams = p.teams, page = p.page, changed = changed, clear = {},
            t0 = p.t0, t_phase = now, preload_ms = VRFW.battle_bay_pages.ms(p.t0), late = 0}
  local state = VRFW.battle_bay_pages.load_state()
  VRFW.battle_bay_pages.log("swap", p.page, "after", p.frames, "frames", B.pend.preload_ms, "ms", state)
end

function VRFW.battle_bay_pages.done(p, state, plates, failed)
  local B = VRFW.battle_bay_pages
  B.pend = nil
  VRFW.battle_bay_pages.release_spares()
  VRFW.battle_bay_pages.log("reveal", p.page, "after", p.frames, "frames", state, "plates", plates)
  VRFW.battle_bay_pages.log(string.format("ready %s in %d ms (preload %d ms, reveal %d ms), late %d, failed %s", tostring(p.page),
               VRFW.battle_bay_pages.ms(p.t0), p.preload_ms or -1, p.reveal_ms or -1, p.late or 0, failed or "none"))
end

function VRFW.battle_bay_pages.pump()
  local B = VRFW.battle_bay_pages
  local p = B.pend
  if p == nil then
    return
  end
  p.frames = p.frames + 1
  local state, busy, loading = VRFW.battle_bay_pages.load_state()
  if p.frames <= B.LOG_FRAMES then
    VRFW.battle_bay_pages.log(p.phase, p.page, "frame", p.frames, state)
  end
  if p.phase == "preload" then
    if not busy then
      VRFW.battle_bay_pages.swap()
    elseif VRFW.battle_bay_pages.over(p, B.PRELOAD_MS, B.PRELOAD_STEPS) then
      VRFW.battle_bay_pages.log("preload timeout", p.page, VRFW.battle_bay_pages.ms(p.t0), "ms", state)
      VRFW.battle_bay_pages.swap()
    end
    return
  end
  local all = true
  for i in pairs(p.changed) do
    if loading[i] then
      p.clear[i] = 0
      all = false
    else
      p.clear[i] = (p.clear[i] or 0) + 1
      if p.clear[i] < B.SETTLE then
        all = false
      end
    end
  end
  if p.phase == "reveal" then
    if all then
      p.reveal_ms = VRFW.battle_bay_pages.ms(p.t_phase)
      VRFW.battle_bay_pages.done(p, state, VRFW.battle_bay_pages.show_nodes(p.changed), nil)
      return
    end
    if not VRFW.battle_bay_pages.over(p, B.REVEAL_MS, B.REVEAL_STEPS) then
      return
    end
    p.reveal_ms = VRFW.battle_bay_pages.ms(p.t_phase)
    p.phase = "late"
  end
  local show, rest = {}, {}
  for i in pairs(p.changed) do
    if (p.clear[i] or 0) >= B.SETTLE then
      show[i] = true
    else
      rest[i] = true
    end
  end
  local plates = ""
  if next(show) ~= nil then
    plates = VRFW.battle_bay_pages.show_nodes(show)
    if p.late > 0 or next(rest) ~= nil then
      VRFW.battle_bay_pages.log("late crests in", p.page, VRFW.battle_bay_pages.slots(show), "at", VRFW.battle_bay_pages.ms(p.t0), "ms")
    end
  end
  p.changed = rest
  if next(rest) == nil then
    VRFW.battle_bay_pages.done(p, state, plates, nil)
    return
  end
  if p.late == 0 then
    for _ in pairs(rest) do
      p.late = p.late + 1
    end
    VRFW.battle_bay_pages.log("crests late", p.page, VRFW.battle_bay_pages.slots(rest), "hidden until in", state)
  end
  -- LATE_MS after the turn began (its steps without the clock)
  local over
  if p.t0 ~= nil and VRFW.battle_bay_pages.now() ~= nil then
    over = VRFW.battle_bay_pages.ms(p.t0) >= B.LATE_MS
  else
    over = p.frames >= B.LATE_STEPS
  end
  if over then
    VRFW.battle_bay_pages.done(p, state, plates, VRFW.battle_bay_pages.slots(rest))
  end
end

-- A mod's screen that only hid the grid's layers (the crest textures stay loaded) calls
function VRFW.battle_bay_pages.keep_crests(on)
  VRFW.battle_bay_pages.crests_kept = on == true
end

-- A team panel card instance set up by the game (OnSetupLayer, after the game's own priority).
function VRFW.battle_bay_pages.card_over_pitch(layer, idx)
  local B = VRFW.battle_bay_pages
  local pitch = funcLuaMenuCommand(B.GET_PRIO, B.PANEL_PITCH[layer], 0)
  local card = funcLuaMenuCommand(B.GET_PRIO, layer, idx)
  if type(pitch) ~= "number" or type(card) ~= "number" or card > pitch then
    return
  end
  funcLuaMenuCommand(B.SET_PRIO, layer, idx, pitch + 1, true)
  if idx == 0 then
    VRFW.battle_bay_pages.log("panel cards " .. tostring(layer) .. " over the pitch: priority " .. tostring(card) .. " -> "
                 .. tostring(pitch + 1))
  end
end

function VRFW.battle_bay_pages.redraw(turn)
  local B = VRFW.battle_bay_pages
  turn = turn == true
  if not turn then
    VRFW.battle_bay_pages.cancel("redraw")
  end
  local changed = {}
  for i = 0, VRFW.battle_bay_pages.grid_slot_count() - 1 do
    local team, unlocked, check, lock = funcLuaCommand(B.SLOT, i)
    if type(team) == "number" then
      local show = team ~= 0
      local was = B.hidden_slots[i] ~= true
      local same = turn and was == show and B.drawn[i] == (show and team or 0)
      if not turn or was ~= show then
        funcLuaMenuCommand(711242136, B.GRID, i, show)
      end
      if show and not same then
        changed[i] = true
        funcLuaMenuCommand(801406373, B.GRID, i, 643056375 --[[gray_out]], 1, 1, 1)
        local kept = not turn and B.crests_kept == true and was and B.drawn[i] == team
        if (not turn or B.hidden_slots[i] == true) and not kept then
          funcLuaMenuCommand(4176779611 --[[reset icon]], B.GRID, i, B.EMBLEM_TEX)
        end
        SetupEmblemIcon(i, team, unlocked == true, check == true)
        funcLuaMenuCommand(2158717427 --[[node visible]], B.GRID, B.EMBLEM_NODE, not turn, i)
        if not turn then
          VRFW.battle_bay_pages.restore_marks(i)
        end
      end
      B.hidden_slots[i] = not show
      B.drawn[i] = show and team or 0
    end
  end
  VRFW.battle_bay_pages.lock_sync()
  return changed
end

function VRFW.battle_bay_pages.lock_look(lock, gold)
  local B = VRFW.battle_bay_pages
  funcLuaMenuCommand(3405944500, B.LOCK, B.LOCK_OFF, not gold, lock)
  funcLuaMenuCommand(3405944500, B.LOCK, B.LOCK_ON, gold, lock)
  funcLuaMenuCommand(3781155141, B.LOCK, lock, B.LOCK_ANIME, gold and 0 or 2, B.LOCK_ANIME_TYPE)
end

function VRFW.battle_bay_pages.lock_sync()
  local B = VRFW.battle_bay_pages
  local held = {}
  for i = 0, VRFW.battle_bay_pages.grid_slot_count() - 1 do
    local team, unlocked, _, lock = funcLuaCommand(B.SLOT, i)
    if type(lock) == "number" and lock >= 0 then
      local on = type(team) == "number" and team ~= 0 and B.hidden_slots[i] ~= true
      if on then
        VRFW.battle_bay_pages.lock_look(lock, unlocked == true)
      end
      funcLuaMenuCommand(711242136, B.LOCK, lock, on)
      held[lock] = true
    end
  end
  local n = funcLuaMenuCommand(1175615627, B.LOCK)
  if type(n) == "number" then
    for k = 0, n - 1 do
      if not held[k] then
        funcLuaMenuCommand(711242136, B.LOCK, k, false)
      end
    end
  end
  B.lock_sync_due = false
  B.hint_key = false
end

-- The lock hint of the focused slot.
function VRFW.battle_bay_pages.hint_off()
  local B = VRFW.battle_bay_pages
  if B.hint_lock ~= nil then
    funcLuaMenuCommand(2158717427 --[[node visible]], B.LOCK, B.LOCK_GUIDE, false, B.hint_lock)
    funcLuaMenuCommand(2735666188, B.LOCK, B.TEXT, false, B.hint_lock)
  end
  B.hint_lock = nil
  B.hint_key = nil
end

-- Every padlock instance's balloon and text hidden but `keep`'s (a padlock instance, or nil).
function VRFW.battle_bay_pages.guides_off(keep)
  local B = VRFW.battle_bay_pages
  local n = funcLuaMenuCommand(1175615627, B.LOCK)
  if type(n) ~= "number" then
    return
  end
  for k = 0, n - 1 do
    if k ~= keep then
      funcLuaMenuCommand(2158717427 --[[node visible]], B.LOCK, B.LOCK_GUIDE, false, k)
      funcLuaMenuCommand(2735666188, B.LOCK, B.TEXT, false, k)
    end
  end
end

function VRFW.battle_bay_pages.hint()
  local B = VRFW.battle_bay_pages
  local cur = funcLuaMenuCommand(2603265800 --[[focus index]], B.GRID)
  if type(cur) ~= "number" or cur < 0 then
    return
  end
  local ok, locked, text, chain, buzz = pcall(funcLuaCommand, B.UNLOCK, cur)
  if not ok then
    return
  end
  if buzz == true then
    funcLuaCommand(1917805374, B.SE_NG)
  end
  local team, _, _, lock = funcLuaCommand(B.SLOT, cur)
  local key = nil
  if locked == true and type(text) == "number" and text ~= 0 and not B.hidden then
    -- Text ids are u32 crc32s.
    key = table.concat({ tostring(cur), tostring(team), tostring(text), tostring(chain), tostring(lock) }, ":")
  end
  if key == B.hint_key then
    return
  end
  VRFW.battle_bay_pages.hint_off()
  VRFW.battle_bay_pages.guides_off(lock)
  if key == nil or type(lock) ~= "number" or lock < 0 then
    return
  end
  local s = funcLuaCommand(B.TEXT_GET, text)
  if type(s) ~= "string" or s == "" then
    return
  end
  local has, name = funcLuaCommand(B.TEAM_INFO, team, 2)
  name = (has and type(name) == "string") and name or ""
  chain = type(chain) == "string" and chain or ""
  s = s:gsub("{team}", function() return name end)
  s = s:gsub("{chain}", function() return chain end)
  funcLuaMenuCommand(1083631230, B.LOCK, B.TEXT, s, lock)
  funcLuaMenuCommand(1172899594, B.LOCK, lock, B.TEXT)
  funcLuaMenuCommand(2158717427 --[[node visible]], B.LOCK, B.LOCK_GUIDE, true, lock)
  funcLuaMenuCommand(2735666188, B.LOCK, B.TEXT, true, lock)
  B.hint_lock = lock
  B.hint_key = key
end

function VRFW.battle_bay_pages.can_turn()
  local B = VRFW.battle_bay_pages
  if not B.on or B.hidden then
    return false
  end
  if funcLuaMenuCommand(2640875187, B.OPTLIST, 0, B.MENU) == true then
    return false
  end
  if funcLuaMenuCommand(2231168902, B.SUBWIN) == true then
    return false
  end
  if funcLuaMenuCommand(2640875187, B.DIFFWIN, 0, B.MENU) == true then
    return false
  end
  return true
end

-- Sets the function a turn asks first (delta, mode): it may prepare the target page's rows and answer another delta.
function VRFW.battle_bay_pages.set_before_turn(fn)
  VRFW.battle_bay_pages.before_turn = fn
end

-- One frame of the strip's pointer targets: hovering lights a target, a left click makes its turn.
function VRFW.battle_bay_pages.pointer_step()
  local B = VRFW.battle_bay_pages
  local hot, ev = nil, nil
  if B.on and not B.hidden and B.tex_ready and B.pend == nil then
    ev = B.ptr.poll()
    hot = ev.hot
    if hot ~= nil and not VRFW.battle_bay_pages.can_turn() then
      hot = nil
    end
  else
    B.ptr.forget()
  end
  if hot ~= B.hover then
    B.hover = hot
    VRFW.battle_bay_pages.draw()
  end
  local turn = hot ~= nil and ev.left and ev.click == hot and B.zone_turn[hot] or nil
  if turn ~= nil then
    VRFW.battle_bay_pages.turn(turn[1], turn[2])
  end
end

-- mode 0 = page (L1 / R1), 1 = category (the bank's filter key, Tab), 2 = season (L2 / R2)
function VRFW.battle_bay_pages.turn(d, mode)
  local B = VRFW.battle_bay_pages
  VRFW.battle_bay_pages.query()
  if not VRFW.battle_bay_pages.can_turn() then
    return
  end
  if (mode == 0 and B.total <= 1) or (mode == 1 and B.cats <= 1) or (mode == 2 and B.seasons < 2) then
    return
  end
  local from = {B.season, B.cat, B.page}
  local cursor = funcLuaMenuCommand(2603265800, B.GRID)
  -- a mod may prepare the target page's rows first, and answer another delta
  if type(B.before_turn) == "function" then
    local ok, delta = pcall(B.before_turn, d, mode)
    if not ok then
      VRFW.battle_bay_pages.log("before_turn error: " .. tostring(delta))
    elseif type(delta) == "number" then
      d = delta
    end
  end
  local page = funcLuaCommand(B.CMD, d, mode)
  if type(page) ~= "number" then
    return
  end
  VRFW.battle_bay_pages.query()
  if from[1] == B.season and from[2] == B.cat and from[3] == B.page then
    return
  end
  if mode == 2 then
    VRFW.battle_bay_pages.load_info()   -- the categories of the new season (their count / names may differ)
    B.cat_cursor = {}
  end
  funcLuaCommand(1917805374, 2500047763 --[[sy0005]])
  VRFW.battle_bay_pages.preload(string.format("s%d c%d p%d", B.season, B.cat, B.page))
  -- the cursor stays on its slot (a category turn: the slot left on that category), or the last filled one on a short page
  local to = cursor
  if mode == 1 and type(cursor) == "number" then
    B.cat_cursor[from[2]] = cursor
    to = B.cat_cursor[B.cat] or cursor
  end
  if type(to) == "number" and B.count > 0 then
    to = math.min(to, B.count - 1)
  end
  if type(to) == "number" and to ~= cursor then
    local n = funcLuaMenuCommand(1175615627, B.GRID) or 0
    funcLuaMenuCommand(1778826357, B.GRID, to, true)
    funcLuaMenuCommand(381797568, B.GRID, 3313461902 --[[cursor]], to, n)
  end
  VRFW.battle_bay_pages.draw()
  VRFW.battle_bay_pages.log(string.format("turn mode %d %+d -> season %d/%d category %d/%d page %d/%d cursor %s 1P slot %s", mode, d,
               B.season, B.seasons, B.cat, B.cats, B.page, B.pages, tostring(cursor), tostring(B.p1slot)))
end

do
  local init = OnInit
  function OnInit(...)
    local r = table.pack(init(...))
    local ok, err = pcall(function()
      VRFW.battle_bay_pages.hidden = false
      VRFW.battle_bay_pages.shown, VRFW.battle_bay_pages.asked = {}, {}
      VRFW.battle_bay_pages.cat_cursor = {}
      VRFW.battle_bay_pages.query()
      VRFW.battle_bay_pages.load_info()
      local B = VRFW.battle_bay_pages
      B.ptr = B.ptr or VRFW.pointer.new()
      B.ptr.reset()
      B.hover = nil
      local names = {}
      for i = 1, math.min(B.cats, B.TABS_MAX) do
        names[#names + 1] = B.catinfo[i] and B.catinfo[i].key or "?"
      end
      local snames = {}
      for i = 0, B.seasons do
        snames[#snames + 1] = B.seasoninfo[i] and (B.seasoninfo[i].key ~= "" and B.seasoninfo[i].key or "all") or "?"
      end
      VRFW.battle_bay_pages.log(string.format("open page %d/%d categories %d [%s] pages %d seasons %d [%s] textures %d", B.page, B.pages,
                   B.cats, table.concat(names, " "), B.total, B.seasons, table.concat(snames, " "), #B.textures))
    end)
    if not ok then
      VRFW.battle_bay_pages.log("init error", tostring(err))
    end
    return table.unpack(r, 1, r.n)
  end

  local function ours(a1)
    local B = VRFW.battle_bay_pages
    return a1 == B.LAYER or a1 == B.BG or a1 == B.TAB_PLATE or a1 == B.TAB_ICON or a1 == B.SEASON_ICON
  end

  local setup = OnSetupLayer
  function OnSetupLayer(a1, a2, ...)
    if ours(a1) then
      VRFW.host.menu_command(711242136, a1, a2, false)
      VRFW.battle_bay_pages.shown = {}
      pcall(VRFW.battle_bay_pages.draw)
      return
    end
    local r = table.pack(setup(a1, a2, ...))
    if VRFW.battle_bay_pages.PANEL_PITCH[a1] ~= nil then
      local ok, err = pcall(VRFW.battle_bay_pages.card_over_pitch, a1, a2)
      if not ok then
        VRFW.battle_bay_pages.log("card priority error", tostring(err))
      end
    end
    return table.unpack(r, 1, r.n)
  end

  local open = OnOpenLayer
  function OnOpenLayer(a1, a2, ...)
    if ours(a1) then
      VRFW.battle_bay_pages.shown = {}
      pcall(VRFW.battle_bay_pages.draw)
      return
    end
    if a1 == VRFW.battle_bay_pages.GRID or a1 == VRFW.battle_bay_pages.LOCK then
      VRFW.battle_bay_pages.lock_sync_due = true   -- the game gave the padlocks out: shown / hidden on the next Step
    end
    return open(a1, a2, ...)
  end

  local fn = OnFunction
  function OnFunction(a1, a2, ...)
    local B = VRFW.battle_bay_pages
    local d, mode = nil, nil
    if a1 == B.FN_PREV then d, mode = -1, 0
    elseif a1 == B.FN_NEXT then d, mode = 1, 0
    elseif a1 == B.FN_CAT_PREV then d, mode = -1, 1
    elseif a1 == B.FN_CAT_NEXT then d, mode = 1, 1
    elseif a1 == B.FN_SEASON then d, mode = 1, 2
    elseif a1 == B.FN_SEASON_PREV then d, mode = -1, 2
    end
    if d ~= nil then
      local ok, err = pcall(VRFW.battle_bay_pages.turn, d, mode)
      if not ok then
        VRFW.battle_bay_pages.log("turn error", tostring(err))
      end
      return 1
    end
    return fn(a1, a2, ...)
  end

  local back = OnBack
  function OnBack(a1, a2, ...)
    if a1 == VRFW.battle_bay_pages.GRID then
      pcall(VRFW.battle_bay_pages.cancel, "back")
      VRFW.host.command(VRFW.battle_bay_pages.RESET)
    end
    return back(a1, a2, ...)
  end

  local setupIcon = SetupEmblemIcon
  function SetupEmblemIcon(a1, a2, a3, a4, ...)
    local r = table.pack(setupIcon(a1, a2, a3, a4, ...))
    if type(a1) == "number" then
      VRFW.battle_bay_pages.drawn[a1] = a2 or 0
    end
    if (a2 == nil or a2 == 0) and VRFW.battle_bay_pages.on and (VRFW.battle_bay_pages.total > 1 or VRFW.battle_bay_pages.seasons >= 2) then
      VRFW.host.menu_command(711242136, VRFW.battle_bay_pages.GRID, a1, false)
      if type(a1) == "number" then
        VRFW.battle_bay_pages.hidden_slots[a1] = true
      end
    end
    return table.unpack(r, 1, r.n)
  end

  local marks = UpdateEmblemIconMesh
  if marks ~= nil then
    function UpdateEmblemIconMesh(a1, ...)
      if type(a1) == "number" then
        VRFW.battle_bay_pages.marks[a1] = table.pack(a1, ...)
      end
      return marks(a1, ...)
    end
  end

  local step = Step
  function Step(...)
    local r = {n = 0}
    if step ~= nil then
      r = table.pack(step(...))
    end
    local B = VRFW.battle_bay_pages
    if B.on and not B.tex_ready then
      local ok, ready = pcall(VRFW.battle_bay_pages.poll_textures_ready)
      if ok and ready then
        VRFW.battle_bay_pages.shown = {}
        local dok, derr = pcall(VRFW.battle_bay_pages.draw)
        if not dok then
          VRFW.battle_bay_pages.log("draw error", tostring(derr))
        end
      end
    end
    if B.pend ~= nil then
      local ok, err = pcall(VRFW.battle_bay_pages.pump)
      if not ok then
        VRFW.battle_bay_pages.log("turn step error", tostring(err))
        pcall(VRFW.battle_bay_pages.cancel, "error")
      end
    end
    if B.ptr ~= nil then
      local pok, perr = pcall(VRFW.battle_bay_pages.pointer_step)
      if not pok then
        VRFW.battle_bay_pages.log("pointer error, the strip's pointer targets are off: " .. tostring(perr))
        B.ptr = nil
      end
    end
    if B.lock_sync_due == true and B.on and B.pend == nil then
      local lok, lerr = pcall(VRFW.battle_bay_pages.lock_sync)
      if not lok then
        B.lock_sync_due = false
        VRFW.battle_bay_pages.log("padlock sync error", tostring(lerr))
      end
    end
    if B.hint_err == nil then
      local hok, herr = pcall(VRFW.battle_bay_pages.hint)
      if not hok then
        B.hint_err = tostring(herr)
        VRFW.battle_bay_pages.log("unlock hint error (hint off)", B.hint_err)
      end
    end
    return table.unpack(r, 1, r.n)
  end
end
-- ===== EVT vrfw_bb_pages END =====
